from __future__ import annotations

from collections import Counter
import re

from ..assurance import DesignCoverageEntry


def _anchor(entry: DesignCoverageEntry) -> str:
    value = re.sub(r"[^\w\- ]", "", f"{entry.section}. {entry.title}".lower())
    return value.replace(" ", "-")


def design_coverage_markdown(entries: tuple[DesignCoverageEntry, ...]) -> str:
    counts = Counter(entry.status for entry in entries)
    lines = [
        "# Design Coverage",
        "",
        "> Generated by `./hfx generate`. Do not edit manually.",
        "",
        "This page summarizes the current Design Book coverage. The complete per-section evidence map remains in [`assurance/design-coverage.json`](../../assurance/design-coverage.json).",
        "Software verification never substitutes for physical evidence or a publication decision.",
        "",
        "## Summary",
        "",
    ]
    for status in sorted(counts):
        lines.append(f"- `{status}`: {counts[status]}")
    lines.extend(
        [
            "",
            "",
            "## Open Or Release-Bounding Work",
            "",
            "Only sections with remaining work, a release boundary, or a non-complete status are listed here.",
            "",
            "| Section | Subject | Status | Owner | Remaining boundary |",
            "| ---: | --- | --- | --- | --- |",
        ]
    )
    visible = tuple(
        entry
        for entry in entries
        if entry.remaining or entry.release_blocking or entry.status != "software-verified"
    )
    for entry in visible:
        remaining = " ".join(entry.remaining) if entry.remaining else "No open software gap."
        if entry.physical_evidence_required:
            remaining += " Physical evidence is required."
        lines.append(
            f"| {entry.section} | [{entry.title}](../{entry.chapter.removeprefix('docs/')}#"
            f"{_anchor(entry)}) | `{entry.status}` | "
            f"`{entry.owner}` | {remaining} |"
        )
    lines.extend(
        [
            "",
            "## Reading The Complete Record",
            "",
            "- Read the [Design Book](../architecture/design-book.md) for implemented architecture and rationale.",
            "- Inspect [`assurance/design-coverage.json`](../../assurance/design-coverage.json) for every section, evidence path, owner, and status.",
            "- Read [release gates](release-gates.md) for the smaller set of product-level checks.",
        ]
    )
    return "\n".join(lines) + "\n"
